return {
	["desc.Cadence"] = "Une jeune femme aux cheveux blonds, avec un bandana bleu et une tunique rouge, qui tient une torche bien haut, une dague à la ceinture.",
	["desc.Melody"] = "La mère de Cadence : des cheveux roux sous un bandana rouge, une robe verte et un tablier, une torche à la main et le luth d'or dans le dos.",
	["desc.Aria"] = "La mère de Mélodie : une femme âgée aux cheveux gris, en longue robe marron et armure de cuir, qui tient une pelle.",
	["desc.Dorian"] = "Le père de Cadence : un homme pâle aux longs cheveux roux, avec une écharpe et une cape vertes, et une armure dorée.",
	["desc.Eli"] = "L'oncle de Cadence : un homme costaud à l'épaisse barbe rousse, avec un chapeau noir et un lourd tablier.",
	["desc.Monk"] = "Un moine chauve en robe bleue avec une ceinture jaune, qui s'incline les mains jointes.",
	["desc.Dove"] = "Une douce jeune femme aux cheveux blonds et à la robe bleu canard, une colombe blanche posée sur la tête et une fleur à la main.",
	["desc.Coda"] = "Un double violet et démoniaque de Cadence, avec des cornes blanches, une longue queue et une dague.",
	["desc.Bolt"] = "Une femme à la peau foncée et aux cheveux violets noués en chignon, en tunique jaune, qui manie une lance.",
	["desc.Bard"] = "Un barde chauve et barbu, en chemise bleue et pantalon jaune, qui chante en jouant du luth.",
	["desc.Nocturna"] = "Une vampire à la peau bleu pâle, aux oreilles pointues, aux cheveux roux et aux ailes de chauve-souris, en chemise blanche et gilet sombre, qui tient une épée courbe.",
	["desc.Diamond"] = "Un danseur à la peau foncée et aux cheveux noirs courts, en pantalon orange, qui s'élance dans un coup de pied sauté.",
	["desc.Mary"] = "Une jeune bergère aux cheveux bruns coiffés en deux couettes, avec un tablier, qui tient une longue houlette, un agneau tout duveteux à ses côtés.",
	["desc.Tempo"] = "Une silhouette à la peau violette, avec un masque de métal et un pantalon bouffant, un pendule doré à la ceinture et des étincelles qui crépitent dans ses deux mains.",
	["desc.Reaper"] = "Une silhouette encapuchonnée en robe violette, au visage de crâne blanc et aux yeux rouges, entourée d'âmes roses qui flottent.",
	["desc.Coldsteel_Coldsteel"] = "Une fille aux très longues couettes turquoise, avec un haut gris sans manches, une cravate turquoise et une jupe noire, qui tient un poireau.",
	["desc.Goldman_Goldman"] = "Un chevalier en armure bleue aux cornes dorées sur le casque, qui tient son épelle, une pelle en forme de lame, entouré de gemmes qui flottent.",
	["desc.Sync_Chaunter"] = "Un fantôme pâle et rapiécé en forme de sac, des clous plantés dans la tête, qui porte une lanterne verte.",
	["desc.Sync_Klarinetta"] = "Une chevalière blonde en armure d'argent, avec une cape rouge et or, qui manie une longue épée.",
	["desc.Sync_Suzu"] = "Une guerrière à la peau grise, un masque rouge sur la bouche, en robe blanche et bleu canard, qui tient une arme d'hast à longue lame.",
	["desc.Slime"] = "Un slime vert vif aux yeux creux. Il sautille sur place et ne quitte jamais sa case ; il ne fait que vous barrer le passage.",
	["desc.Slime2"] = "Un grand slime bleu aux yeux creux et à la bouche béante. Il fait des allers-retours de haut en bas entre deux cases.",
	["desc.Slime3"] = "Un slime orange aux yeux creux. Il tourne autour d'un petit carré : droite, bas, gauche, haut, encore et encore.",
	["desc.Slime4"] = "Un slime bleu pâle fait de glace. Il tourne autour d'un petit carré en se déplaçant en diagonale, et laisse une plaque de glace en mourant.",
	["desc.Slime5"] = "Un slime rouge et orange fait de feu. Il tourne autour d'un petit carré en se déplaçant en diagonale, et laisse des braises en mourant.",
	["desc.Slime6"] = "Un slime violet luminescent. Il zigzague : droite, bas à gauche, droite, haut à gauche, encore et encore.",
	["desc.Slime7"] = "Un slime noir. Il suit une boucle : droite, bas à gauche, gauche, haut à droite, encore et encore.",
	["desc.Slime8"] = "Un slime blanc. Il tourne autour d'un grand carré : deux pas à droite, deux en bas, deux à gauche, deux en haut.",
	["desc.Motherslime"] = "Une grosse mère slime verte. Elle tourne autour d'un grand carré et se divise en tout petits slimes en mourant.",
	["desc.Tinyslime"] = "Un tout petit slime vert. Il sautille au hasard.",
	["desc.Skeleton"] = "Un squelette aux bras levés. Il marche vers vous et lève les bras juste avant de bouger.",
	["desc.Skeleton2"] = "Un squelette aux bras levés, plus résistant que le blanc. Il marche vers vous ; presque mort, il perd sa tête et court à l'aveugle en ligne droite.",
	["desc.Skeleton4"] = "Un squelette de cristal scintillant. Il marche vers vous et se brise en éclats de cristal quand il est détruit.",
	["desc.Bat"] = "Une petite chauve-souris aux ailes membraneuses, avec des crocs et la langue pendante. Elle volette au hasard et mord tout ce qu'elle percute.",
	["desc.Bat3"] = "Une chauve-souris verte à crocs. Elle volette au hasard dans huit directions, diagonales comprises.",
	["desc.Bat4"] = "Une chauve-souris gris foncé aux yeux jaunes. Elle volette au hasard, mais mord toujours quand vous êtes à côté d'elle.",
	["desc.BatMiniboss"] = "Une énorme chauve-souris aux ailes griffues et à la gueule pleine de crocs. Elle volette au hasard.",
	["desc.Monkey"] = "Un singe violet aux longs bras. Il vous saute dessus et s'agrippe : vous ne pouvez plus bouger tant que vous ne l'avez pas fait lâcher, et il vous fait perdre votre multiplicateur de pièces. Il est plus résistant tant qu'il s'accroche.",
	["desc.Monkey3"] = "Un singe vert avec un bandeau. Il vous saute dessus et s'agrippe, et tant qu'il s'accroche, vos directions sont inversées.",
	["desc.Monkey4"] = "Un singe magique rose aux bras levés. Il vous saute dessus et s'agrippe, et sa prise vous téléporte ailleurs dans le niveau.",
	["desc.Ghost"] = "Un fantôme bleu pâle, une flèche à travers la tête et le visage hurlant. Quand vous avancez vers lui, il s'estompe et ne peut pas être blessé ; il redevient solide quand vous vous éloignez.",
	["desc.Wraith"] = "Un esprit de fumée rouge aux longs filaments traînants. Il surgit de nulle part près de vous et vous poursuit.",
	["desc.Zombie"] = "Un zombie qui traîne les pieds, aux cheveux bleus, à la peau violette et aux vêtements déchirés. Il marche en ligne droite et fait demi-tour quand quelque chose le bloque.",
	["desc.ZombieElectric"] = "Une zombie à la coupe afro violette et à la peau jaune crépitante d'électricité. Elle marche en ligne droite et fait demi-tour quand quelque chose la bloque.",
	["desc.Armadillo"] = "Un tatou à la lourde carapace. Quand il vous voit, il se roule en boule et fonce sur vous en ligne droite, puis reste étourdi un moment là où il s'arrête.",
	["desc.Armoredskeleton"] = "Un squelette accroupi derrière un grand bouclier en bois peint d'un crâne. Le bouclier bloque les coups de face et ne fait que le repousser ; frappez-le par le côté ou par derrière.",
	["desc.Armoredskeleton2"] = "Un squelette accroupi derrière un grand bouclier peint. Le bouclier bloque les coups de face ; presque mort, il perd sa tête et court à l'aveugle en ligne droite.",
	["desc.Armoredskeleton4"] = "Un squelette de cristal accroupi derrière un grand bouclier qui bloque les coups de face. Il se brise en éclats de cristal quand il est détruit.",
	["desc.Banshee"] = "Une grande femme fantomatique en robe flottante, aux longs cheveux blancs, avec un crâne à bec en guise de visage et de longues griffes. Quand elle est touchée, elle hurle et étouffe la musique autour de vous.",
	["desc.Clone"] = "Une copie de vous aux yeux rouges luisants. Chaque fois que vous bougez, elle bouge dans le sens opposé, comme dans un miroir.",
	["desc.Golem"] = "Un énorme golem de roche couvert de mousse et de petites fleurs. Très lent et très résistant, il creuse à travers les murs pour vous atteindre.",
	["desc.Golem3"] = "Un énorme golem de vase violette, dégoulinant de slime vert. Très lent et très résistant, il creuse à travers les murs pour vous atteindre.",
	["desc.Mole"] = "Une taupe bleue avec des lunettes de soleil. Elle s'enfouit sous terre en se déplaçant et remonte à la surface pour attaquer.",
	["desc.Mushroom"] = "Un champignon au chapeau tacheté avec un petit visage. Il ne bouge jamais, mais toutes les quelques pulsations, il libère des spores qui blessent tout ce qui l'entoure.",
	["desc.MushroomExploding"] = "Un champignon enflé qui dort jusqu'à ce qu'on le frappe. Une fois réveillé, il explose.",
	["desc.MushroomLight"] = "Un champignon lumineux qui éclaire la zone autour de lui. Il ne bouge jamais.",
	["desc.Nightmare"] = "Un démon à l'allure de cheval fait de fumée sombre, aux yeux luisants et aux crocs acérés. Il creuse à travers les murs pour vous atteindre.",
	["desc.Tarmonster"] = "Une masse de goudron rouge sombre avec un seul œil et un sourire plein de dents. Elle se cache dans une flaque de goudron jusqu'à ce que vous approchiez, puis vous agrippe et vous entraîne avec elle. Elle laisse du goudron en mourant.",
	["desc.Wight"] = "Un esprit de fumée verte aux longs filaments traînants. Il surgit de nulle part près de vous et vous poursuit.",
	["desc.Skeletonmage"] = "Un mage squelette aux longs cheveux blancs, en robe sombre, avec un bâton crépitant de magie rose. À deux cases de distance, son vent vous attire juste à côté de lui.",
	["desc.Beetle"] = "Un scarabée à la carapace semblable à des briques de pierre et aux pattes orange flamboyant. Quand il vous remarque, il laisse des braises autour de lui ; frapper sa carapace le repousse et répand des braises en croix.",
	["desc.Beetle2"] = "Un scarabée à la carapace de glace bleue. Quand il vous remarque, il laisse de la glace autour de lui ; frapper sa carapace le repousse et répand de la glace en croix.",
	["desc.Cauldron"] = "Un chaudron de fer rempli de braises rougeoyantes. Il reste simplement là ; le briser répand des braises.",
	["desc.Cauldron2"] = "Un chaudron de fer rempli de glace. Il reste simplement là ; le briser répand de la glace.",
	["desc.Trapcauldron"] = "Un chaudron de fer plein de braises rougeoyantes, avec une gueule pleine de dents. Il ressemble à un chaudron ordinaire jusqu'à ce que vous approchiez, puis il se réveille et mord. Il répand des braises en mourant.",
	["desc.Trapcauldron2"] = "Un chaudron de fer plein de glace, avec une gueule pleine de dents. Il ressemble à un chaudron ordinaire jusqu'à ce que vous approchiez, puis il se réveille et mord. Il répand de la glace en mourant.",
	["desc.Fireelemental"] = "Une flamme vivante avec des yeux. Elle laisse une traînée de braises et creuse à travers les murs.",
	["desc.Iceelemental"] = "Une créature de glace hérissée de pointes. Elle laisse une traînée de glace et creuse à travers les murs.",
	["desc.Ghast"] = "Un esprit magenta aux longs bras en forme de tentacules. Il surgit de nulle part près de vous et esquive votre premier coup.",
	["desc.Goblin"] = "Un gobelin aux longues oreilles, armé d'un couteau courbe. Quand vous avancez vers lui, il se dérobe et ne peut pas être blessé ; il redevient solide quand vous vous éloignez.",
	["desc.Hellhound"] = "Un chien maigre et cornu aux écailles jaunes et au poitrail rouge flamboyant. Il laisse des braises en mourant.",
	["desc.Shovemonster"] = "Une brute fantomatique au visage de crâne, cachée derrière une grande dalle de pierre. Elle ne vous blesse pas ; elle vous repousse.",
	["desc.Skeletonknight"] = "Un squelette monté sur un cheval squelettique pâle, qui tient un bouclier rouge. Son bouclier bloque les coups de face ; un coup le fait tomber de cheval, et il continue le combat à pied.",
	["desc.Skeletonknight2"] = "Un squelette monté sur un cheval squelettique pâle, avec un bouclier qui bloque les coups de face. Un coup le fait tomber de cheval ; presque mort, il perd sa tête et court à l'aveugle.",
	["desc.Skeletonknight4"] = "Un squelette de cristal monté sur un cheval pâle, avec un bouclier qui bloque les coups de face. Un coup le fait tomber de cheval ; il se brise en éclats de cristal quand il est détruit.",
	["desc.Yeti"] = "Un énorme yéti à la fourrure hirsute bleue et blanche, des boules de neige dans les poings. À chaque pas, il frappe dans ses mains et blesse tout ce qui l'entoure ; il creuse à travers les murs et laisse de la glace en mourant.",
	["desc.Blademaster"] = "Un chevalier en armure de plaque, avec une longue épée et une cape. Il pare votre premier coup et riposte.",
	["desc.Gargoyle"] = "Une gargouille de pierre accroupie sur un piédestal. Elle reste immobile comme une statue.",
	["desc.Ghoul"] = "Une créature fantomatique bleu canard aux filaments flottants et à la large bouche. Elle surgit de nulle part près de vous et esquive votre premier coup.",
	["desc.GoblinBomber"] = "Un petit gobelin rouge à cheval sur une bombe géante en forme de crâne, une torche à la main. Son attaque est une explosion, et il lâche une bombe allumée en mourant.",
	["desc.SleepingGoblin"] = "Un gobelin somnolent avec un oreiller et une pelle. Il somnole jusqu'à ce que vous approchiez, puis se réveille et creuse pour s'éloigner de vous.",
	["desc.Harpy"] = "Une harpie : une femme aux cheveux bleu canard, aux ailes à plumes vertes et aux pattes d'oiseau. Elle vole vers vous.",
	["desc.Lich"] = "Un sorcier squelettique en longue robe et turban, qui tient un bâton. À deux cases de distance, il vous lance un sort de confusion qui inverse vos directions.",
	["desc.Mommy"] = "Une grande momie couverte de bandelettes, qui berce de plus petites momies dans ses nombreux bras. Elle est lente et appelle des momies pour combattre à sa place.",
	["desc.Mummy"] = "Une momie couverte de bandelettes qui avance en traînant les pieds.",
	["desc.Ogre"] = "Un énorme ogre vert à un seul œil, aux cheveux violets et à la gueule pleine de crocs, qui brandit une massue. Il est lent, mais sa massue fracasse les cases devant lui.",
	["desc.Pixie"] = "Une minuscule étincelle aux ailes luminescentes bleues, jaunes et roses. Si elle vous atteint, elle disparaît et vous soigne ; si vous la frappez, elle explose.",
	["desc.Sarcophagus"] = "Un cercueil de pierre marqué d'une croix, d'où sortent des bras osseux. Il ne bouge jamais, mais libère sans cesse des squelettes jusqu'à ce que vous le brisiez.",
	["desc.Spider"] = "Une grosse araignée orange et velue aux yeux verts. Elle se tapit dans les murs et vous saute dessus.",
	["desc.Warlock"] = "Un sorcier encapuchonné avec un vide obscur en guise de visage et un bâton d'étincelles. Quand il meurt, il échange sa place avec vous.",
	["desc.Wraith2"] = "Une apparition jaune lumineuse, comme une flamme à la bouche béante. Elle apparaît près de vous, vous agrippe et maudit vos cœurs.",
	["desc.Devil"] = "Un petit diable avec un crâne de bélier en guise de tête, qui éclot d'un œuf blanc fendu. Sa coquille le protège ; une fois la coquille brisée, il bouge à chaque pulsation.",
	["desc.ElectricMage"] = "Un magicien en longue robe et chapeau pointu, qui tient un bâton surmonté d'une ampoule lumineuse. Il tire des orbes électriques qui volent en ligne droite.",
	["desc.ElectricOrb"] = "Un orbe électrique crépitant qui vole en ligne droite.",
	["desc.Evileye"] = "Une masse à tentacules avec un énorme œil unique, d'autres yeux au bout de tiges et un sourire plein de dents. Elle attend, puis se jette sur vous depuis plusieurs cases.",
	["desc.Gorgon"] = "Une gorgone aux serpents en guise de cheveux et à la queue de serpent. Quand elle vous atteint, elle vous change en pierre, puis s'effrite.",
	["desc.Metrognome"] = "Un gnome à lunettes de protection, perché sur un métronome doré monté sur des pattes d'araignée mécaniques. Son attaque touche toutes les cases autour de lui, et il se téléporte quand il est touché.",
	["desc.Orc"] = "Un orc musclé avec une massue et un bouclier marqué d'une clé de sol. Le bouclier bloque les coups de face, et il perd une pulsation chaque fois qu'il change de direction.",
	["desc.Skull"] = "Un crâne géant flottant avec un œil luisant. Le frapper libère un squelette.",
	["desc.WaterBall"] = "Une bulle d'eau flottante au visage de crâne. Elle s'accroche à vous et éclate, inondant le sol.",
	["desc.WaterBall2"] = "Une bulle de goudron flottante au visage de crâne. Elle s'accroche à vous et éclate, laissant du goudron sur le sol.",
	["desc.Dragon"] = "Un grand dragon à la tête cornue, aux longs crocs et couvert d'écailles. Il creuse à travers les murs pour vous atteindre.",
	["desc.Dragon2"] = "Un grand dragon rouge ailé aux longs crocs. Quand vous êtes dans son axe, il crache du feu.",
	["desc.Dragon3"] = "Un grand dragon bleu aux longs crocs et aux cornes. Quand vous êtes devant lui, il crache un souffle de glace qui gèle.",
	["desc.Minotaur"] = "Un minotaure aux cornes dorées recourbées comme une lyre et à l'anneau dans le nez. Quand il vous voit, il charge en ligne droite en défonçant les murs, et reste étourdi quand il s'arrête.",
	["desc.Leprechaun"] = "Un lutin au chapeau vert orné d'un trèfle et à la barbe rousse, qui porte un sac d'or. Il vous fuit, vole votre or s'il vous touche, et disparaît au bout d'un moment.",
	["desc.Fakewall"] = "Un pan de mur couvert de mousse qui s'ouvre en une énorme gueule pleine de crocs. Il ressemble à un mur jusqu'à ce que vous approchiez.",
	["desc.Fakewall2"] = "Un mur de briques jaunes de magasin qui s'ouvre en une gueule pleine de dents. Il ressemble à un mur jusqu'à ce que vous approchiez.",
	["desc.Trapchest"] = "Un coffre au trésor avec une gueule pleine de dents et une langue. Il ressemble à un coffre jusqu'à ce que vous approchiez, puis il se réveille et mord.",
	["desc.Trapchest4"] = "Une caisse en bois avec une gueule pleine de dents. Elle ressemble à une caisse jusqu'à ce que vous approchiez.",
	["desc.Trapchest5"] = "Un baril en bois avec une gueule pleine de dents. Il ressemble à un baril jusqu'à ce que vous approchiez.",
	["desc.Trapchest6"] = "Un sanctuaire de pierre surmonté de flammes, avec une gueule pleine de dents. Il ressemble à un sanctuaire jusqu'à ce que vous approchiez.",
	["desc.Skeletonspearman"] = "Un squelette armé d'une longue lance.",
	["desc.Skeletontank"] = "Un squelette caché sous une grosse carapace rocheuse. Il charge en ligne droite.",
	["desc.Troll"] = "Un énorme troll vert. Quand il est touché, il charge vers vous.",
	["desc.Toad"] = "Un petit crapaud vert. Il sautille vers vous.",
	["desc.KingConga"] = "King Conga : un énorme zombie vert à l'allure de singe, avec un masque rouge et or, qui joue des congas sur son trône pendant qu'une ligne Conga de zombies danse autour de lui. Rater une pulsation le met en colère, et il quitte son trône.",
	["desc.ZombieSnake"] = "Un zombie qui danse dans la ligne Conga de King Conga, en suivant celui de devant.",
	["desc.Deathmetal"] = "Death Metal : un squelette encapuchonné vêtu de noir, avec une faux, derrière un énorme bouclier en forme de crâne, entouré de chauves-souris bleues qui tourbillonnent. Son bouclier bloque les coups de face, et il change de tactique à mesure qu'il est blessé.",
	["desc.King"] = "Deep Blues : un roi à la peau bleue, à la barbe rousse et couronné, qui joue de la contrebasse, à la tête d'une armée d'échecs aux pièces à tête de crâne. Battez le roi pour gagner.",
	["desc.Pawn"] = "Un pion d'échecs au visage de crâne. Il avance vers votre côté de l'échiquier et devient une reine s'il atteint l'autre bout.",
	["desc.Knight"] = "Un cavalier d'échecs en forme de cheval à tête de crâne. Il saute en L.",
	["desc.Bishop"] = "Un fou d'échecs au visage de crâne, coiffé d'une mitre. Il se déplace en diagonale.",
	["desc.Rook"] = "Une tour d'échecs au visage de crâne. Elle se déplace en ligne droite.",
	["desc.Queen"] = "La reine des échecs. Elle se déplace dans toutes les directions.",
	["desc.Coralriff"] = "Riff corallien : une pieuvre géante rouge sombre qui joue des instruments avec ses tentacules : une guitare basse, une trompette et d'autres encore. Ses tentacules surgissent de l'eau autour de vous.",
	["desc.Tentacle"] = "Un tentacule de Riff corallien qui surgit de l'eau, agrippé à un instrument.",
	["desc.DeadRinger"] = "Dead Ringer : une silhouette massive en armure dorée, avec un casque en forme de cloche, qui brandit un marteau, un gong à ses côtés. Il charge à travers la salle et fait sonner les cloches.",
	["desc.Necrodancer"] = "Le NecroDancer : un sorcier mort-vivant à la peau bleue, avec une longue barbe blanche, des yeux rouges luisants et une cape rouge, qui tient un luth d'or. Il relève les morts pour qu'ils combattent pour lui.",
	["desc.Necrodancer2"] = "Le NecroDancer, à la peau bleue et à la barbe blanche, sa cape rouge grande ouverte, le poing levé et un sourire plein de crocs.",
	["desc.LuteDragon"] = "Le luth d'or devenu vivant : un long dragon doré aux épines roses. Sa tête est la caisse du luth, avec une gueule pleine de dents.",
	["desc.LuteHead"] = "La tête du luth d'or : la caisse du luth, avec une gueule pleine de dents. Elle crache des boules de feu.",
	["desc.Fortissimole"] = "Taupissimo : une taupe géante en armure dorée, avec un casque en forme de château, qui chante dans un micro sous les acclamations de danseurs squelettes. Elle creuse et surgit du sol.",
	["desc.Frankensteinway"] = "Frankensteinway : une énorme machine violette dont le corps est un piano, avec des poings gigantesques. Elle électrifie le sol en se déplaçant.",
	["desc.Conductor"] = "La chef d'orchestre : une scientifique aux cheveux blonds en bataille, avec des lunettes de laiton et un manteau violet, reliée à ses machines par des câbles et des bras de laiton.",
	["desc.Shopkeeper"] = "Un vendeur trapu et barbu, en turban et en robe, une perche et une lanterne sur l'épaule. Il chante avec la musique, plus fort à mesure que vous approchez. Ne l'attaquez pas.",
	["desc.ShopkeeperGhost"] = "Le fantôme pâle et lumineux d'un vendeur. Il vous poursuit.",
	["desc.Merlin"] = "Un petit magicien aux cheveux blancs, avec un grand chapeau pointu bleu, une robe bleue étoilée et un bâton de bois.",
	["desc.Hephaestus"] = "Un forgeron musclé en tablier de cuir, le marteau levé au-dessus d'une enclume.",
	["desc.Medic"] = "Une grande silhouette à la peau violette, avec des cornes et une couronne de pointes, qui tient un trident et un parchemin.",
	["desc.Weaponmaster"] = "Un combattant masqué vêtu de violet, qui fait tournoyer une lame.",
	["desc.Beastmaster"] = "Un homme costaud à moustache, qui tient un fouet enroulé.",
	["desc.Bossmaster"] = "Une femme forte aux longs cheveux orange et au haut bleu canard, appuyée sur un marteau.",
	["desc.Janitor"] = "Un vieil homme à la barbe blanche et au manteau vert, qui tient une lanterne et une serpillière à côté d'un seau.",
	["desc.Diamonddealer"] = "Un renard en manteau violet, qui brandit un diamant étincelant.",
	["desc.Trainer"] = "Un livre ouvert sur un piédestal de pierre : le Codex.",
	["desc.Transmogrifier"] = "Un scientifique aux cheveux sombres et aux lunettes de protection, qui tient des potions lumineuses.",
	["desc.Pawnbroker"] = "Un gobelin vert perché sur un énorme tas d'armes, de boucliers et de trésors.",
	["desc.Conjurer"] = "Un esprit bleu et fantomatique qui flotte au-dessus d'un coffre au trésor.",
	["scene.title.necrodancer"] = "Illustration de l'écran titre : Cadence, torche levée et dague à la main, fait face à un fantôme bleu pâle, une flèche à travers la tête, dans un cimetière sombre. Au-dessus d'eux, le logo du jeu entre deux crânes.",
	["scene.title.amplified"] = "Illustration de l'écran titre d'Amplified : Nocturna, l'épée à la main, affronte un mage squelette au chapeau violet dont le bâton crépite d'éclairs.",
	["scene.title.synchrony"] = "Illustration de l'écran titre de Synchrony : Klarinetta avec sa longue épée, Chantôme, le fantôme rapiécé à la lanterne verte, et Suzu avec son arme d'hast, sous le logo de Synchrony.",
	["scene.title.halloween"] = "Illustration de l'écran titre d'Halloween, Un bonbon ou un sort : Chantôme, le fantôme rapiécé à la lanterne verte, et Cadence, une citrouille-lanterne sur la tête, parmi des citrouilles lumineuses.",
	["scene.title.christmas"] = "Illustration de l'écran titre de Noël, Joyeuses cryptes de fin d'année : Cadence en manteau rouge de père Noël avec sa pelle ; derrière elle, un immense mort-vivant à la barbe blanche coiffé d'un bonnet de père Noël, des fantômes et une faucheuse encapuchonnée remplissent le ciel enneigé.",
	["scene.zone1"] = "La crypte : des sols de terre sombre et tassée, et des murs de terre pleins de racines, d'os et de crânes, certains en blocs de pierre. Tant que votre multiplicateur de pièces est actif, le sol clignote en damier au rythme des pulsations.",
	["scene.zone2"] = "Des sols de pierre moussue verte et bleu canard, des murs de terre envahis de feuilles et de petits champignons orange, et des murs de pavés pâles.",
	["scene.zone3"] = "Cette profondeur est divisée en deux : un côté chaud de roche rougeâtre aux sols orange incandescents, et un côté froid de roche gris-bleu aux sols bleus glacés.",
	["scene.zone4"] = "Les catacombes : des sols bleu foncé et des murs de briques violettes bordés de squelettes, de crânes et de bannières.",
	["scene.zone5"] = "Un laboratoire : des sols violet foncé aux dalles dorées et cyan, et des murs de briques magenta couverts de tuyaux, de câbles et de machines.",
	["scene.boss"] = "Une arène de boss : un sol de pierre sombre, et des murs de pierre pâle incrustés de crânes et d'os.",
	["scene.boss.NECRODANCER"] = "La scène du NecroDancer : une piste de danse verte encadrée d'enceintes violettes géantes.",
	["cs.intro.1"] = "La nuit dans un cimetière. Cadence, une jeune femme aux cheveux blonds, avec un bandana bleu et une tunique rouge, grimpe parmi les pierres tombales avec une torche et une pelle, puis se met à creuser.",
	["cs.intro.2"] = "Sa pelle perce le sol et une fumée violette jaillit autour d'elle.",
	["cs.intro.3"] = "Le sol cède. Elle tombe dans les ténèbres, frôlant des mains squelettiques qui tentent de l'agripper.",
	["cs.intro.4"] = "Elle s'écrase sur le sol de pierre d'une crypte, parmi les os, et reste immobile dans une mare de sang.",
	["cs.intro.5"] = "Une lumière violette envahit la salle. Un sorcier mort-vivant à la peau bleue, à la longue barbe blanche et à la cape rouge se dresse au-dessus d'elle : le NecroDancer.",
	["cs.intro.6"] = "Par sa magie, il lui arrache de la poitrine son cœur, qui brille, et le brandit en souriant.",
	["cs.intro.7"] = "Cadence se réveille sur le sol et se relève avec sa pelle, une fumée violette s'échappant de sa poitrine.",
	["cs.intro.8"] = "Elle regarde droit devant elle, déterminée.",
	["cs.cadence1.1"] = "Une maison en bois éclairée par une bougie. La petite Cadence jette un œil depuis l'embrasure d'une porte.",
	["cs.cadence1.2"] = "Son père Dorian, coiffé d'une casquette verte, range une carte et des outils dans un coffre.",
	["cs.cadence1.3"] = "La petite Cadence baisse les yeux, triste, à côté de son oncle Eli, un grand homme à la barbe rousse et au chapeau noir.",
	["cs.cadence1.4"] = "Des années plus tard, Cadence adolescente fouille dans le vieux coffre de son père, une pelle appuyée à côté.",
	["cs.cadence1.5"] = "Elle en sort ses notes et une carte, avec un grand sourire.",
	["cs.cadence1.6"] = "Depuis l'embrasure de la porte, oncle Eli la regarde en fronçant les sourcils, tandis que Cadence détourne les yeux.",
	["cs.cadence1.7"] = "Cadence serre la carte contre elle, déterminée.",
	["cs.cadence2.1"] = "Un enterrement sur une colline verdoyante. Des personnes en deuil, en robes sombres, se tiennent près d'un cercueil rouge couvert de fleurs. La petite Cadence chante à côté.",
	["cs.cadence2.2"] = "Derrière elle, oncle Eli pointe un doigt accusateur vers son père Dorian.",
	["cs.cadence2.3"] = "Vu d'en haut, Dorian écarte les mains d'un air suppliant, tandis qu'Eli le domine de toute sa hauteur.",
	["cs.cadence2.4"] = "En gros plan : Dorian détourne le regard, tendu ; Eli serre le poing.",
	["cs.cadence2.5"] = "Cadence leur tourne le dos et pose la main sur le cercueil tandis que des pétales rouges s'envolent.",
	["cs.cadence3.1"] = "Un pique-nique ensoleillé au bord d'un lac. Une femme au foulard rouge, Mélodie, joue du luth tandis que Dorian fait tournoyer la petite Cadence. Un cheval broute non loin.",
	["cs.cadence3.2"] = "La petite Cadence danse et rit ; ses parents s'enlacent derrière elle.",
	["cs.cadence3.3"] = "Plus tard, Mélodie est alitée, malade, la tête bandée et des taches sombres sur le bras. Dorian lui tient la main.",
	["cs.cadence3.4"] = "Dorian se détourne, troublé, tandis que la petite Cadence observe depuis l'embrasure de la porte.",
	["cs.cadence4.1"] = "Cadence est agenouillée près d'un homme pâle aux longs cheveux roux, en armure dorée : son père, Dorian.",
	["cs.cadence4.2"] = "Dans une salle de la crypte aux arches violettes, le NecroDancer écarte les bras, un luth d'or dans une main.",
	["cs.cadence4.3"] = "Une flamme dans son autre main se change en cœur battant de Cadence, qu'il brandit pour la narguer.",
	["cs.cadence4.4"] = "Cadence, avec sa pelle et sa dague, se tient aux côtés de Dorian, qui empoigne un lourd marteau doré.",
	["cs.cadence5.1"] = "Le NecroDancer gît vaincu sur le sol. Dorian, en armure dorée, tient son luth d'or ; derrière lui, Cadence brille d'une lumière violette.",
	["cs.cadence5.2"] = "Cadence, la pelle à la main, fait face à son père qui s'éloigne avec le luth.",
	["cs.cadence5.3"] = "Dehors, sous une lune verte, Cadence et Dorian émergent parmi les pierres tombales et les racines tordues, Dorian portant le luth.",
	["cs.melody0.1"] = "La nuit au cimetière, sous une lune verte. Dorian joue du luth d'or au-dessus d'un cercueil ouvert, tandis que Cadence est agenouillée à côté. Dans le cercueil repose une femme aux cheveux roux : Mélodie.",
	["cs.melody0.2"] = "Les yeux de Mélodie s'ouvrent d'un coup dans un éclair de lumière violette.",
	["cs.melody0.3"] = "Elle se redresse dans le cercueil, et Cadence et Dorian sourient.",
	["cs.melody0.4"] = "Une vision du NecroDancer vaincu, d'où s'échappe une fumée violette.",
	["cs.melody0.5"] = "À la maison, Mélodie, avec un bandana rouge et une robe verte, prend une pelle et le luth d'or.",
	["cs.melody0.6"] = "Une torche brandie bien haut, elle descend par un puits de pierre jusque dans la crypte, tandis que des tentacules verts sortent des murs.",
	["cs.melody1.1"] = "Une chambre de malade. Mélodie est alitée, pâle, une rose rouge sur la couverture. Dorian, avec sa casquette verte, est assis à côté d'elle et lui tient la main.",
	["cs.melody1.2"] = "En gros plan : Dorian se penche sur elle, les yeux plissés et durs, tandis qu'elle reste allongée, faible, la tête bandée.",
	["cs.melody2.1"] = "Dans la cuisine d'une chaumière, une femme aux cheveux gris munie d'un luth d'or, Aria, relève doucement le menton de la jeune Mélodie.",
	["cs.melody2.2"] = "Plus tard, la silhouette sombre d'Aria franchit la porte, tandis que Mélodie lui tourne le dos, la tête baissée.",
	["cs.melody3.1"] = "Un village au crépuscule. Aria joue de son luth d'or au chevet d'un homme malade, tandis que la jeune Mélodie le soigne.",
	["cs.melody3.2"] = "Un villageois armé d'une torche crie et pointe du doigt Aria, sur le seuil d'une porte ; d'autres se rassemblent avec des fourches et des faux.",
	["cs.melody3.3"] = "Mélodie et Aria se tiennent ensemble avec le luth, encerclées par les fourches de la foule, dans un éclat de lumière violette.",
	["cs.melody4.1"] = "Dans la salle de la crypte, Mélodie joue du luth d'or au-dessus du NecroDancer, étendu sur le sol dans sa cape rouge.",
	["cs.melody4.2"] = "Il se relève lentement : peau bleue, yeux rouges, mains griffues tendues.",
	["cs.melody4.3"] = "Vu d'en haut, Mélodie continue de jouer tandis que le NecroDancer rampe vers elle.",
	["cs.melody4.4"] = "Gros plan sur le visage grimaçant du NecroDancer, aux yeux rouges luisants.",
	["cs.melody4.5"] = "En gros plan : Mélodie gratte le luth calmement et ne s'arrête jamais.",
	["cs.melody4.6"] = "Le NecroDancer se dresse et hurle de rage dans un éclat de lumière violette.",
	["cs.melody5.1"] = "Le NecroDancer recule en titubant vers un cercueil de pierre ouvert.",
	["cs.melody5.2"] = "Un éclair de lumière violette : une femme aux cheveux gris en robe violette lui plante une dague dans le dos, sous les yeux de Mélodie.",
	["cs.melody5.3"] = "Sa cape rouge s'effondre sur le sol aux pieds de la femme.",
	["cs.melody5.4"] = "Dans la pénombre de la crypte, Mélodie se tourne vers la femme aux cheveux gris, qui tient toujours la dague.",
	["cs.nocturna1.1"] = "Une crypte pleine d'étranges machines. Nocturna, une vampire à la peau bleu pâle, aux cheveux roux et aux ailes de chauve-souris, brandit une torche à côté d'un crâne géant.",
	["cs.nocturna1.2"] = "Un squelette gît affalé contre des tuyaux et des cadrans, tandis qu'une étincelle court le long d'un câble.",
	["cs.nocturna1.3"] = "Vu d'en bas, Nocturna se dresse avec la torche, ailes déployées.",
	["cs.nocturna1.4"] = "Elle descend en volant un escalier sombre, la torche en avant.",
	["cs.nocturna2.1"] = "Nocturna brandit une torche dans une salle de machines aux cadrans lumineux, et tend la main vers le mur.",
	["cs.nocturna2.2"] = "Elle avance dans un long couloir métallique bordé de câbles et de lumières.",
	["cs.nocturna2.3"] = "En gros plan : sa main bleue touche d'épais câbles crépitant d'électricité jaune.",
	["cs.nocturna2.4"] = "Vu d'en haut, elle suit les câbles lumineux sur le sol.",
	["cs.nocturna2.5"] = "Elle poursuit son vol, ailes déployées, dans un tunnel éclairé par le feu.",
	["cs.nocturna3.1"] = "Un squelette casqué, relié aux machines par des câbles, est affalé au milieu d'étincelles jaunes.",
	["cs.nocturna3.2"] = "En gros plan : Nocturna l'examine, l'air peu impressionné.",
	["cs.nocturna3.3"] = "Elle s'accroupit près du squelette et tire sur les câbles plantés dans son dos.",
	["cs.nocturna3.4"] = "Elle tient le faisceau de câbles à deux mains, puis serre les poings.",
	["cs.nocturna3.5"] = "Elle s'éloigne seule dans un long couloir ; un autre squelette relié aux câbles pend au mur.",
	["cs.nocturna4.1"] = "Un retour en arrière : une jeune femme à la peau brune et aux cheveux bruns bouclés hurle et tend la main tandis qu'un vampire bleu aux yeux rouges la mord au cou, une église derrière eux sous un ciel violet.",
	["cs.nocturna4.2"] = "Sa peau devient bleu pâle et ses cheveux roux, tandis qu'un feu brûle derrière elle.",
	["cs.nocturna4.3"] = "Dans une forêt de bouleaux blancs, Nocturna, ailée, est accroupie au-dessus d'un animal à terre, tandis que des yeux rouges l'observent depuis l'obscurité.",
	["cs.nocturna4.4"] = "Un grand vampire aux longs cheveux roux flottants sort de l'obscurité en rampant vers elle.",
	["cs.nocturna4.5"] = "En gros plan : Nocturna regarde ses mains ensanglantées, puis serre les poings.",
	["cs.nocturna5.1"] = "Un laboratoire rempli de machines. Un énorme corps mécanique violet repose sur une table, la poitrine lumineuse, dans une gerbe d'étincelles.",
	["cs.nocturna5.2"] = "Nocturna, une épée à la main, s'avance vers lui.",
	["cs.nocturna5.3"] = "Une femme en manteau violet et lunettes de laiton, aux cheveux blonds en bataille et aux lèvres bleues, se détourne de son travail : la chef d'orchestre.",
	["cs.nocturna5.4"] = "Nocturna pointe son épée vers elle à travers la vapeur.",
	["cs.nocturna5.5"] = "La chef d'orchestre croise les bras, l'air peu impressionné.",
	["cs.nocturna5.6"] = "Elle regarde Nocturna de haut avec un sourire narquois.",
	["cs.nocturna5.7"] = "Elle s'approche d'une machine et en sort un luth d'or.",
	["cs.nocturna5.8"] = "Le luth flamboie d'une lumière jaune entre ses mains.",
	["cs.nocturna5.9"] = "Nocturna lève son épée.",
	["cs.nocturna5.10"] = "Nocturna bondit sur elle tandis que des éclairs jaillissent du luth.",
	["cs.nocturna6.1"] = "Nocturna se tient au-dessus de la machine détruite de la chef d'orchestre, d'où s'élève de la fumée, l'épée à la main.",
	["cs.nocturna6.2"] = "Elle regarde sa main ouverte.",
	["cs.nocturna6.3"] = "Une énergie rouge tourbillonne autour d'elle. Ses yeux brillent de rouge et elle sourit, crocs dénudés.",
	["cs.nocturna6.4"] = "Elle saisit un appareil doré crépitant d'éclairs, le lève en hurlant et le fracasse contre un miroir.",
	["cs.nocturna6.5"] = "Elle s'empare du luth d'or et le soulève au-dessus de sa tête, les yeux flamboyants.",
	["cs.nocturna6.6"] = "Ses yeux redeviennent normaux. Elle hésite.",
	["cs.nocturna6.7"] = "Dans le miroir fêlé, elle voit son moi humain : une femme à la peau brune, aux cheveux bruns bouclés et aux lunettes rondes.",
	["cs.nocturna6.8"] = "Elle abaisse le luth et le tient calmement, ses yeux désormais dorés.",
	["cs.nocturna6.9"] = "La lumière tombe d'un puits au-dessus d'elle. Sa silhouette s'élève dans le faisceau et disparaît.",
	["cs.introDlc.1"] = "La nuit dans un cimetière, sous la pleine lune et un ciel violet. Un rat aux yeux roses luisants rampe le long d'une branche.",
	["cs.introDlc.2"] = "Des feuilles volent au-dessus des tombes.",
	["cs.introDlc.3"] = "Une main sombre et griffue sort de terre devant un tombeau, tandis qu'une forme aux yeux rouges est perchée au-dessus.",
	["cs.introDlc.4"] = "Une silhouette encapuchonnée aux yeux rouges luisants se dresse dans l'obscurité.",
	["cs.introDlc.5"] = "En gros plan : des yeux rouges de vampire et un sourire narquois.",
	["cs.introDlc.6"] = "Une silhouette ailée se pose à côté d'un vieux tombeau de pierre.",
	["cs.introDlc.7"] = "Nocturna se tient sous la pleine lune, les mains sur les hanches, ailes de chauve-souris déployées.",
	["cs.introDlc.8"] = "Elle frappe du pied et la dalle de pierre du tombeau vole en éclats.",
	["cs.introDlc.9"] = "Elle scrute le tombeau brisé, où un passage rose lumineux descend dans les profondeurs.",
	["cs.introDlc.10"] = "Elle plonge à l'intérieur, et des mains mortes surgissent de la terre derrière elle.",
	["cs.aria0.1"] = "Dans la crypte, Mélodie joue du luth d'or. Derrière elle se tient sa mère Aria : cheveux gris, robe violette, armure de cuir marron, une dague à la main.",
	["cs.aria0.2"] = "En gros plan : Mélodie la fusille du regard, en colère.",
	["cs.aria0.3"] = "Aria baisse les yeux, honteuse, éclairée par la lueur des torches.",
	["cs.aria0.4"] = "La colère de Mélodie se change en tristesse ; elle continue de jouer.",
	["cs.aria0.5"] = "Aria tend la main ouverte à sa fille.",
	["cs.aria1.1"] = "Aria joue du luth d'or devant une arche de pierre et de crânes.",
	["cs.aria1.2"] = "Dans un sanctuaire sombre envahi par la végétation, elle lève le luth près d'un piédestal de pierre où brûle une flamme rose.",
	["cs.aria1.3"] = "Le luth prend vie entre ses mains : son manche s'enroule comme un dragon doré et des griffes lui poussent, tandis que la flamme rose s'embrase.",
	["cs.aria2.1"] = "Une taverne. Un jeune barde à la barbe rousse et à la chemise bleue joue du luth sur une petite scène, tandis que les buveurs l'ignorent.",
	["cs.aria2.2"] = "Plus tard, dans une forêt sombre, le même barde, avec un sac et un bâton de marche, se protège les yeux d'un luth d'or qui brille sur une pierre.",
	["cs.aria3.1"] = "Le barde, Octavian, joue du luth d'or pour une armée de monstres : un énorme minotaure rouge aux cornes dorées, un slime vert plein d'os, des squelettes brandissant des épées.",
	["cs.aria3.2"] = "Bien avant, Aria traverse la crypte vide avec une pelle et une torche.",
	["cs.aria3.3"] = "En gros plan : Octavian, désormais mort-vivant à la peau bleue, avec une longue barbe blanche et une cape rouge, joue du luth, les yeux las et creux.",
	["cs.aria3.4"] = "Le luth lui glisse des mains et s'efface dans l'obscurité.",
	["cs.aria4.1"] = "Aria, une pelle à ses côtés, joue du luth d'or au-dessus d'un cercueil de pierre ouvert où repose le NecroDancer.",
	["cs.aria4.2"] = "Des mains bleues agrippent le bord du cercueil tandis qu'il se réveille.",
	["cs.aria4.3"] = "Le NecroDancer se lève et tend la main vers le luth tandis qu'Aria continue de jouer.",
	["cs.aria4.4"] = "Dans un éclat de lumière violette, Aria tend le luth et les mains bleues du NecroDancer se referment dessus.",
	["cs.aria4.5"] = "Il s'empare du luth et repousse Aria d'un coup, les yeux luisants de rouge.",
	["cs.aria5.1"] = "Dans le sanctuaire envahi par la végétation, Aria se protège les yeux tandis que des éclairs violets jaillissent du piédestal autour du luth d'or.",
	["cs.aria5.2"] = "Elle fracasse le luth sur le piédestal et des rayons de lumière violette jaillissent.",
	["cs.aria5.3"] = "Des éclairs violets l'enveloppent et elle s'affaisse contre la pierre.",
	["cs.aria5.4"] = "Au coucher du soleil, au sommet d'une colline, Cadence se tient devant une pierre tombale gravée du nom d'Aria.",
	["cs.aria5.5"] = "Mélodie et Dorian la rejoignent, bras dessus bras dessous, tandis que le soleil se couche.",
}
